  cold_war: { pan:[95,14,26], dial:[80,14,62], face:[74,12,70], ink:[100,26,16], nd:[6,84,52],  bez:[90,10,44], lamp:[110,80,92], txt:[86,18,64], glow:.5 },
  bakelite: { pan:[18,34,17], dial:[30,12,66], face:[34,8,76],  ink:[20,34,12], nd:[2,86,50],  bez:[24,30,36], lamp:[26,88,94], txt:[28,22,58], glow:.45 },
  xray:     { pan:[210,52,17], dial:[206,40,26], face:[204,36,30], ink:[190,4,96], nd:[190,4,99], bez:[200,30,44], lamp:[186,70,96], txt:[196,14,86], glow:.9 }
