const LBLS = ['MAIN BUS','FEEDWATER','TURBINE','EXCITER','COOLANT A','COOLANT B','STATOR','MANIFOLD','PLENUM','REACTOR','CONDENSER','SCRUBBER','GOVERNOR','PENSTOCK','BUS TIE','INTERTIE','PREHEAT','SURGE','TAILRACE','DRUM'];
