// ---- panel layout: a seeded grid of instrument tiles (cached) ----
const COLS = clp(4 + Math.round(dens * 3), 4, 7), ROWS = clp(3 + Math.round(dens * 1), 3, 4);
const lkey = COLS + 'x' + ROWS + '|' + (P.seed | 0);
