// ---- cached brushed-panel plate (local coords -> scales live with P.scale) ----
const pkey = P.style + '|' + Math.round(P.hue) + '|' + (P.seed | 0) + '|' + wear.toFixed(2);
if (!S.plate || S.pkey !== pkey) {
