  const BX = 512, BY = 384;
  const g = createGraphics(BX, BY); g.pixelDensity(1); g.colorMode(g.HSB, 360, 100, 100, 100);
  g.noStroke(); g.background(PNH, st.pan[1], st.pan[2]);
  for (let i = 0; i < 2600; i++) {                     // brushed grain
