  // share it across every round gauge; only the needle and the red band are live.
  if (S.face && S.face.remove) S.face.remove();
  const FS = 256, fc = FS * .5, FR = FS * .435;
  const f = createGraphics(FS, FS); f.pixelDensity(1); f.colorMode(f.HSB, 360, 100, 100, 100);
  f.clear(); f.noStroke();
  f.fill(BEH, st.bez[1], st.bez[2] * 1.5); f.ellipse(fc, fc, FR * 2.3);
  f.fill(BEH, st.bez[1], st.bez[2] * .55); f.ellipse(fc, fc, FR * 2.12);
  if (!wire) { f.fill(DIH, st.dial[1], st.dial[2]); f.ellipse(fc, fc, FR * 2); }
  else { f.noFill(); f.stroke(INH, st.ink[1], st.ink[2], 60); f.strokeWeight(1.5); f.ellipse(fc, fc, FR * 2); }
  const fa0 = Math.PI * .78, fa1 = Math.PI * 2.22;
  for (let k = 0; k <= 20; k++) {
