// =================== composite ===================
const sc = clp(P.scale, .4, 2.2);
const PW = 0.94 * W * sc, PH2 = 0.88 * H * sc;
const px0 = P.x * W - PW * .5, py0 = P.y * H - PH2 * .5;
const tw = PW / COLS, th = PH2 / ROWS;
const dc = drawingContext;

noStroke();
background(PNH, st.pan[1], st.pan[2] * .45);
image(S.plate, px0, py0, PW, PH2);

// bay dividers + rivets: the panel reads as bolted-together sections
stroke(PNH, st.pan[1] * .6, st.pan[2] * 1.9, 46); strokeWeight(Math.max(1, u * .0016));
for (let c = 1; c < COLS; c++) line(px0 + c * tw, py0, px0 + c * tw, py0 + PH2);
for (let r = 1; r < ROWS; r++) line(px0, py0 + r * th, px0 + PW, py0 + r * th);
noFill();

textFont('Courier New');
for (let i = 0; i < tiles.length; i++) {
  const t0 = tiles[i], x = px0 + t0.c * tw + tw * .5, y = py0 + t0.r * th + th * .5;
  const R = Math.min(tw, th) * .34;
  const v = clp(S.n[i], 0, 1.05);
  const alarm = v > t0.red;

